+  <a class="skip-link" href="#maincontent">Skip to main content</a>
+  <div id="app"></div>
+
+  <script>
+    const questions = [
+      {
+        id: "q1",
+        legend: "Which languages commonly appear in modern frontend web projects?",
+        help: "Select all answers that are commonly part of browser-based interface work.",
+        choices: [
+          { value: "javascript", label: "JavaScript" },
+          { value: "typescript", label: "TypeScript" },
+          { value: "html", label: "HTML" },
+          { value: "csharp", label: "C#" }
+        ],
+        correct: ["javascript", "typescript", "html"]
+      },
+      {
+        id: "q2",
+        legend: "Which of these are statically typed languages?",
+        choices: [
+          { value: "java", label: "Java" },
+          { value: "csharp", label: "C#" },
+          { value: "ruby", label: "Ruby" },
+          { value: "go", label: "Go" }
+        ],
+        correct: ["java", "csharp", "go"]
+      },
+      {
+        id: "q3",
+        legend: "Which languages are often used for systems programming?",
+        choices: [
+          { value: "rust", label: "Rust" },
+          { value: "c", label: "C" },
+          { value: "python", label: "Python" },
+          { value: "zig", label: "Zig" }
+        ],
+        correct: ["rust", "c", "zig"]
+      }
+    ];
+
+    const state = {
+      errors: {},
+      result: null
+    };
+
+    function QuizHeader() {
+      return `
+        <header class="hero">
+          <p class="eyebrow">Language Lab &middot; Multi-select quiz</p>
+          <h1>Test your instincts on computer languages.</h1>
+          <p>
+            Each question can have more than one correct answer. Choose every option you think fits,
+            then submit to see how closely your selections match the answer key.
+          </p>
+        </header>
+      `;
+    }
+
+    function Choice({ questionId, choice, index }) {
+      const checkboxId = `${questionId}-${index}`;
+      return `
+        <label class="choice" for="${checkboxId}">
+          <input id="${checkboxId}" type="checkbox" name="${questionId}" value="${choice.value}">
+          <span class="choice-text">${choice.label}</span>
+        </label>
+      `;
+    }
+
+    function QuestionField(question, index) {
+      const errorId = `${question.id}-error`;
+      const helpId = question.help ? `${question.id}-help` : "";
+      const describedBy = [helpId, state.errors[question.id] ? errorId : ""].filter(Boolean).join(" ");
+
+      return `
+        <div class="form-field">
+          <fieldset class="question-fieldset"${describedBy ? ` aria-describedby="${describedBy}"` : ""}>
+            <legend class="question-legend">
+              <span class="question-number">${index + 1}</span>
+              ${question.legend}
+            </legend>
+            ${question.help ? `<p class="field-help" id="${helpId}">${question.help}</p>` : ""}
+            <p class="field-error" id="${errorId}"${state.errors[question.id] ? "" : " hidden"}>
+              ${state.errors[question.id] || ""}
+            </p>
+            <div class="choices">
+              ${question.choices.map((choice, choiceIndex) => Choice({ questionId: question.id, choice, index: choiceIndex })).join("")}
+            </div>
+          </fieldset>
+        </div>
+      `;
+    }
+
+    function ResultPanel() {
+      if (!state.result) {
+        return `<div class="result" aria-live="polite"></div>`;
+      }
+
+      return `
+        <div class="result" aria-live="polite">
+          <div class="result-panel ${state.result.kind}">
+            <p class="result-title">${state.result.title}</p>
+            <p class="result-copy">${state.result.message}</p>
+          </div>
+        </div>
+      `;
+    }
+
+    function App() {
+      return `
+        <div class="page-shell">
+          ${QuizHeader()}
+          <main id="maincontent" tabindex="-1">
+            <section class="quiz-card" aria-labelledby="quiz-title">
+              <div class="quiz-meta" aria-hidden="true">
+                <span>3 questions</span>
+                <span>4 choices each</span>
+                <span>Multiple answers allowed</span>
+              </div>
+              <form id="quiz-form" novalidate>
+                <h2 id="quiz-title">Computer language quiz</h2>
+                ${questions.map(QuestionField).join("")}
+                <div class="actions">
+                  <button class="submit-button" type="submit">Submit quiz</button>
+                  ${ResultPanel()}
+                </div>
+              </form>
+            </section>
+          </main>
+        </div>
+      `;
+    }
+
+    function getSelections(form, questionId) {
+      return Array.from(form.querySelectorAll(`input[name="${questionId}"]:checked`)).map((input) => input.value);
+    }
+
+    function setsMatch(left, right) {
+      if (left.length !== right.length) {
+        return false;
+      }
+
+      const rightSet = new Set(right);
+      return left.every((item) => rightSet.has(item));
+    }
+
+    function bindEvents() {
+      const form = document.getElementById("quiz-form");
+      form.addEventListener("submit", handleSubmit);
+
+      form.querySelectorAll('input[type="checkbox"]').forEach((checkbox) => {
+        checkbox.addEventListener("change", () => {
+          const questionId = checkbox.name;
+          if (state.errors[questionId]) {
+            delete state.errors[questionId];
+            render();
+          }
+        });
+      });
+    }
+
+    function handleSubmit(event) {
+      event.preventDefault();
+      const form = event.currentTarget;
+      const nextErrors = {};
+      let firstInvalidInput = null;
+
+      questions.forEach((question) => {
+        const selections = getSelections(form, question.id);
+        if (selections.length === 0) {
+          nextErrors[question.id] = "Error: Select at least one answer for this question.";
+          if (!firstInvalidInput) {
+            firstInvalidInput = form.querySelector(`input[name="${question.id}"]`);
+          }
+        }
+      });
+
+      state.errors = nextErrors;
+
+      if (Object.keys(nextErrors).length > 0) {
+        state.result = {
+          kind: "error",
+          title: "Complete all questions",
+          message: "Pick at least one answer in each question before submitting the quiz."
+        };
+        render();
+        if (firstInvalidInput) {
+          firstInvalidInput.focus();
+        }
+        return;
+      }
+
+      let score = 0;
+      questions.forEach((question) => {
+        const selections = getSelections(form, question.id);
+        if (setsMatch(selections, question.correct)) {
+          score += 1;
+        }
+      });
+
+      state.result = {
+        kind: "success",
+        title: `Score: ${score} / ${questions.length}`,
+        message: score === questions.length
+          ? "Perfect run. You matched every answer set."
+          : "Nice work. You can adjust your selections and submit again any time."
+      };
+      render();
+      document.getElementById("maincontent").focus();
+    }
+
+    function render() {
+      document.getElementById("app").innerHTML = App();
+      bindEvents();
+    }
+
+    render();
+  </script>
+</body>
+</html>
*** End Patch
