                   ${ResultPanel()}
                 </div>
               </form>
             </section>
           </main>
         </div>
       `;
     }

     function getSelections(form, questionId) {
       return Array.from(form.querySelectorAll(`input[name="${questionId}"]:checked`)).map((input) => input.value);
     }

     function setsMatch(left, right) {
       if (left.length !== right.length) {
         return false;
       }

       const rightSet = new Set(right);
       return left.every((item) => rightSet.has(item));
     }

     function bindEvents() {
       const form = document.getElementById("quiz-form");
       form.addEventListener("submit", handleSubmit);

       form.querySelectorAll('input[type="checkbox"]').forEach((checkbox) => {
         checkbox.addEventListener("change", () => {
           const questionId = checkbox.name;
           if (state.errors[questionId]) {
             delete state.errors[questionId];
             render();
           }
         });
       });
     }

     function handleSubmit(event) {
       event.preventDefault();
       const form = event.currentTarget;
       const nextErrors = {};
       let firstInvalidInput = null;

       questions.forEach((question) => {
         const selections = getSelections(form, question.id);
         if (selections.length === 0) {
           nextErrors[question.id] = "Error: Select at least one answer for this question.";
           if (!firstInvalidInput) {
