  <a class="skip-link" href="#maincontent">Skip to main content</a>
  <div class="page-shell">
    <header class="hero">
      <p class="eyebrow">Language Lab &middot; Multi-select quiz</p>
      <h1>Test your instincts on computer languages.</h1>
      <p>
        Each question can have more than one correct answer. Choose every option you think fits,
        then submit to see how closely your selections match the answer key.
      </p>
    </header>

    <main id="maincontent" tabindex="-1">
      <section class="quiz-card" aria-labelledby="quiz-title">
        <div class="quiz-meta" aria-hidden="true">
          <span>3 questions</span>
          <span>4 choices each</span>
          <span>Multiple answers allowed</span>
        </div>

        <form id="quiz-form" novalidate>
          <h2 id="quiz-title">Computer language quiz</h2>

          <div class="form-field">
            <fieldset class="question-fieldset" aria-describedby="q1-help">
              <legend class="question-legend">
                <span class="question-number">1</span>
                Which languages commonly appear in modern frontend web projects?
              </legend>
              <p class="field-help" id="q1-help">Select all answers that are commonly part of browser-based interface work.</p>
              <p class="field-error" id="q1-error" hidden></p>
              <div class="choices">
                <label class="choice" for="q1-0">
                  <input id="q1-0" type="checkbox" name="q1" value="javascript">
                  <span class="choice-text">JavaScript</span>
                </label>
                <label class="choice" for="q1-1">
                  <input id="q1-1" type="checkbox" name="q1" value="typescript">
                  <span class="choice-text">TypeScript</span>
                </label>
                <label class="choice" for="q1-2">
                  <input id="q1-2" type="checkbox" name="q1" value="html">
                  <span class="choice-text">HTML</span>
                </label>
                <label class="choice" for="q1-3">
                  <input id="q1-3" type="checkbox" name="q1" value="csharp">
                  <span class="choice-text">C#</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="form-field">
            <fieldset class="question-fieldset">
              <legend class="question-legend">
                <span class="question-number">2</span>
                Which of these are statically typed languages?
              </legend>
              <p class="field-error" id="q2-error" hidden></p>
              <div class="choices">
                <label class="choice" for="q2-0">
                  <input id="q2-0" type="checkbox" name="q2" value="java">
                  <span class="choice-text">Java</span>
                </label>
                <label class="choice" for="q2-1">
                  <input id="q2-1" type="checkbox" name="q2" value="csharp">
                  <span class="choice-text">C#</span>
                </label>
                <label class="choice" for="q2-2">
                  <input id="q2-2" type="checkbox" name="q2" value="ruby">
                  <span class="choice-text">Ruby</span>
                </label>
                <label class="choice" for="q2-3">
                  <input id="q2-3" type="checkbox" name="q2" value="go">
                  <span class="choice-text">Go</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="form-field">
            <fieldset class="question-fieldset">
              <legend class="question-legend">
                <span class="question-number">3</span>
                Which languages are often used for systems programming?
              </legend>
              <p class="field-error" id="q3-error" hidden></p>
              <div class="choices">
                <label class="choice" for="q3-0">
                  <input id="q3-0" type="checkbox" name="q3" value="rust">
                  <span class="choice-text">Rust</span>
                </label>
                <label class="choice" for="q3-1">
                  <input id="q3-1" type="checkbox" name="q3" value="c">
                  <span class="choice-text">C</span>
                </label>
                <label class="choice" for="q3-2">
                  <input id="q3-2" type="checkbox" name="q3" value="python">
                  <span class="choice-text">Python</span>
                </label>
                <label class="choice" for="q3-3">
                  <input id="q3-3" type="checkbox" name="q3" value="zig">
                  <span class="choice-text">Zig</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="actions">
            <button class="submit-button" type="submit">Submit quiz</button>
            <div class="result" id="quiz-result" aria-live="polite"></div>
          </div>
        </form>
      </section>
    </main>
  </div>

  <script>
    const questions = [
      { id: "q1", helpId: "q1-help", errorId: "q1-error", correct: ["javascript", "typescript", "html"] },
      { id: "q2", helpId: "", errorId: "q2-error", correct: ["java", "csharp", "go"] },
      { id: "q3", helpId: "", errorId: "q3-error", correct: ["rust", "c", "zig"] }
    ];

    const state = {
      errors: {},
      result: null
    };

    function ResultPanel(result) {
      if (!result) {
        return "";
      }

      return `
        <div class="result-panel ${result.kind}">
          <p class="result-title">${result.title}</p>
          <p class="result-copy">${result.message}</p>
        </div>
      `;
    }

    function getSelections(questionId) {
      return Array.from(document.querySelectorAll(`input[name="${questionId}"]:checked`)).map((input) => input.value);
    }

    function setsMatch(left, right) {
      if (left.length !== right.length) {
        return false;
      }

      const rightSet = new Set(right);
      return left.every((item) => rightSet.has(item));
    }

    function updateQuestionState(question) {
      const fieldset = document.querySelector(`input[name="${question.id}"]`).closest("fieldset");
      const error = document.getElementById(question.errorId);
      const describedBy = [question.helpId, state.errors[question.id] ? question.errorId : ""].filter(Boolean).join(" ");

      if (describedBy) {
        fieldset.setAttribute("aria-describedby", describedBy);
      } else {
        fieldset.removeAttribute("aria-describedby");
      }

      error.hidden = !state.errors[question.id];
      error.textContent = state.errors[question.id] || "";
    }

    function renderResult() {
      document.getElementById("quiz-result").innerHTML = ResultPanel(state.result);
    }

    function renderForm() {
      questions.forEach(updateQuestionState);
      renderResult();
    }

    function handleSubmit(event) {
      event.preventDefault();
      const nextErrors = {};
      let firstInvalidInput = null;

      questions.forEach((question) => {
        const selections = getSelections(question.id);
        if (selections.length === 0) {
          nextErrors[question.id] = "Error: Select at least one answer for this question.";
          if (!firstInvalidInput) {
            firstInvalidInput = document.querySelector(`input[name="${question.id}"]`);
          }
        }
      });

      state.errors = nextErrors;

      if (Object.keys(nextErrors).length > 0) {
        state.result = {
          kind: "error",
          title: "Complete all questions",
          message: "Pick at least one answer in each question before submitting the quiz."
        };
        renderForm();
        firstInvalidInput.focus();
        return;
      }

      const score = questions.reduce((total, question) => {
        return total + (setsMatch(getSelections(question.id), question.correct) ? 1 : 0);
      }, 0);

      state.result = {
        kind: "success",
        title: `Score: ${score} / ${questions.length}`,
        message: score === questions.length
          ? "Perfect run. You matched every answer set."
          : "Nice work. You can adjust your selections and submit again any time."
      };

      renderForm();
      document.getElementById("maincontent").focus();
    }

    document.getElementById("quiz-form").addEventListener("submit", handleSubmit);

    document.querySelectorAll('input[type="checkbox"]').forEach((checkbox) => {
      checkbox.addEventListener("change", () => {
        if (state.errors[checkbox.name]) {
          delete state.errors[checkbox.name];
          renderForm();
        }
      });
    });
  </script>
</body>
</html>
