       --success-text: #0e6a3b;
       --error-bg: #fff1f1;
       --error-text: #a22828;
       --shadow: 0 24px 60px rgba(28, 47, 94, 0.14);
     }

     @media (prefers-color-scheme: dark) {
       :root {
         --bg: #09111f;
         --surface: rgba(12, 23, 43, 0.88);
         --surface-strong: #0f1b31;
         --text: #eff4ff;
         --muted: #afbdd8;
         --line: rgba(204, 217, 255, 0.14);
         --primary: #7c97ff;
         --primary-strong: #9cb0ff;
         --accent: #a9b7ff;
         --success-bg: #0f2f22;
         --success-text: #b7f3cc;
         --error-bg: #351616;
         --error-text: #ffbaba;
         --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
       }
     }

     * {
       box-sizing: border-box;
     }

     html,
     body {
       margin: 0;
       min-height: 100%;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top left, rgba(109, 124, 255, 0.18), transparent 32%),
         radial-gradient(circle at top right, rgba(52, 87, 255, 0.14), transparent 28%),
         var(--bg);
       color: var(--text);
     }

     body {
       padding: 24px;
     }

     .skip-link {
       position: absolute;
       left: 16px;
       top: 16px;
       transform: translateY(-180%);
       background: var(--surface-strong);
       color: var(--text);
       padding: 10px 14px;
       border-radius: 999px;
       border: 1px solid var(--line);
       text-decoration: none;
       z-index: 10;
       transition: transform 0.2s ease;
     }

     .skip-link:focus {
       transform: translateY(0);
     }

     .page-shell {
       width: min(100%, 980px);
       margin: 0 auto;
     }

     .hero,
     .quiz-card {
       background: var(--surface);
       backdrop-filter: blur(18px);
       border: 1px solid var(--line);
       box-shadow: var(--shadow);
     }

     .hero {
       padding: clamp(24px, 4vw, 44px);
       border-radius: 32px;
       margin-bottom: 24px;
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 8px;
       margin: 0 0 16px;
       padding: 8px 12px;
       border-radius: 999px;
       background: rgba(52, 87, 255, 0.12);
       color: var(--primary-strong);
       font-size: 0.9rem;
       font-weight: 700;
       letter-spacing: 0.01em;
     }

     h1 {
       margin: 0 0 12px;
       font-size: clamp(2rem, 5vw, 3.5rem);
       line-height: 1.02;
     }

     .hero p {
       margin: 0;
       max-width: 62ch;
       color: var(--muted);
       font-size: 1.05rem;
       line-height: 1.7;
     }

     main {
       outline: none;
     }

     .quiz-card {
       border-radius: 28px;
       padding: clamp(20px, 4vw, 36px);
     }

     .quiz-meta {
       display: flex;
       flex-wrap: wrap;
       gap: 12px;
       margin-bottom: 24px;
       color: var(--muted);
       font-size: 0.95rem;
     }

     .quiz-meta span {
       padding: 8px 12px;
       border-radius: 999px;
       background: rgba(52, 87, 255, 0.08);
       border: 1px solid rgba(52, 87, 255, 0.08);
     }

     form {
       display: grid;
       gap: 20px;
     }

     .form-field {
       border-radius: 24px;
       border: 1px solid var(--line);
       background: color-mix(in srgb, var(--surface-strong) 76%, transparent);
       padding: 20px;
     }

     .question-fieldset {
       margin: 0;
       padding: 0;
       border: 0;
       min-inline-size: auto;
     }

     .question-legend {
       width: 100%;
       margin-bottom: 12px;
       padding: 0;
       font-size: 1.05rem;
       font-weight: 700;
       line-height: 1.5;
     }

     .question-number {
       display: inline-flex;
       align-items: center;
       justify-content: center;
       inline-size: 2rem;
       block-size: 2rem;
       margin-right: 10px;
       border-radius: 999px;
       background: linear-gradient(135deg, var(--primary), var(--accent));
       color: #fff;
       font-size: 0.95rem;
       vertical-align: middle;
     }

     .field-help,
     .field-error {
       margin: 0 0 14px;
       line-height: 1.6;
     }

     .field-help {
       color: var(--muted);
       font-size: 0.96rem;
     }

     .field-error {
       color: var(--error-text);
       background: var(--error-bg);
       border-radius: 16px;
       padding: 10px 12px;
       font-weight: 600;
     }

     .choices {
       display: grid;
       gap: 12px;
     }

     .choice {
       display: flex;
       align-items: flex-start;
       gap: 12px;
       padding: 14px 16px;
       border-radius: 18px;
       border: 1px solid var(--line);
       background: var(--surface-strong);
       cursor: pointer;
       transition: border-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
     }

     .choice:hover {
       border-color: rgba(52, 87, 255, 0.34);
       transform: translateY(-1px);
       box-shadow: 0 12px 22px rgba(52, 87, 255, 0.08);
     }

     .choice input {
       inline-size: 1.15rem;
       block-size: 1.15rem;
       margin-top: 2px;
       accent-color: var(--primary);
       flex: none;
     }

     .choice-text {
       display: block;
       line-height: 1.5;
       font-weight: 600;
     }

     .actions {
       display: flex;
       flex-wrap: wrap;
       gap: 16px;
       align-items: center;
       justify-content: space-between;
       margin-top: 8px;
